// ============================================================================
// REPORT LAYOUT: the node for how the report LOOKS and reads. DATA ONLY (no logic).
// Edit the values between the EDIT lines. A mistake gives a clear 500 (report_misconfigured,
// lines start "Layout:") and nothing is claimed, fetched or sent.
// What you cannot change here, on purpose: values are always escaped, a source that was
// unavailable is always shown as unavailable, an incomplete report always says so (page and email).
// ============================================================================
// ---- EDIT FROM HERE ---------------------------------------------------------
const layout = {
  // Extra CSS added after the built-in style (no "<", no @import, no url(...)).
  css: '',
  // Plain text under the title / at the end of the report.
  intro: '',
  footer: '',
  // Symbol put in front of 'money' values.
  currency: '',
  // Order of the sections, by data source name. Sources you leave out follow in CONFIG order.
  order: [],
  // The PDF page. size: 'A4' | 'A3' | 'Letter' | 'Legal'; landscape: true | false; margin_mm: 0 to 50.
  // null = the renderer's own default page.  Example: { size: 'A4', landscape: true, margin_mm: 12 }
  page: null,
  // The look. accent: a colour like '#0b5394'; font: 'sans' | 'serif' | 'mono'; font_size: 8 to 18 (px).
  // null = the built-in look.  Example: { accent: '#0b5394', font: 'serif', font_size: 11 }
  theme: null,
  // Headline figures shown as cards under the title (at most 8). Each: { source, key, label?, format? }
  //   key:    a key of an object source; a dotted path like 'by_region.west' also works.
  //   agg:    'sum' | 'avg' | 'min' | 'max' | 'count' to total up a list of records (then also give "column",
  //           except for 'count'). key may be left out when the source itself is the list.
  // A source that was unavailable always shows "unavailable"; a value that is not there shows "n/a".
  kpis: [],
  // Per data source (the "name" in DATA_SOURCES_JSON). Everything is optional.
  //   title:      heading (default: the source's label)
  //   show:       only these keys / columns, in this order (default: all)
  //   hide:       leave these keys / columns out
  //   labels:     { key: 'Column heading' }
  //   formats:    { key: 'number' | 'int' | 'money' | 'percent' | 'date' | 'text' }
  //               ('percent' expects a fraction: 0.25 shows as 25%)
  //   max_rows:   most rows shown in a table (1 to 500, default 50)
  //   empty_text: what to say when the source returned nothing
  //   note:       a sentence under the heading
  //   style:      'cards' shows the single values of an object source as cards (default: a table)
  //   sort:       { by: 'column', order: 'asc' | 'desc' } for every list of records in the section
  //   total:      ['column', ...] adds a Total row (summed over ALL rows, also those cut by max_rows)
  //   highlight:  [{ key: 'csat', op: '<', value: 4.5, tone: 'warn' }]  op: > >= < <= == !=; tone: good | warn | bad
  sections: {
    // sales: { title: 'Revenue & Costs', hide: ['average_order_value'], labels: { total_revenue: 'Total revenue' }, formats: { total_revenue: 'money' }, note: 'Figures are before refunds.' },
  },
  // The email. Use {title} {period_start} {period_end} {run_id}.
  // (If the report is incomplete a note saying so is always added to the body.)
  email: {
    subject: '{title} {period_start} - {period_end}',
    body: 'Attached is the {title} for {period_start} to {period_end}.',
  },
};
// ---- STOP EDITING HERE ------------------------------------------------------
const pick = (o, k, d) => (o && o[k] !== undefined && o[k] !== null ? o[k] : d);
const em = pick(layout, 'email', {});
const norm = { page: pick(layout, 'page', null), theme: pick(layout, 'theme', null), kpis: pick(layout, 'kpis', []), css: pick(layout, 'css', ''), intro: pick(layout, 'intro', ''), footer: pick(layout, 'footer', ''), currency: pick(layout, 'currency', ''), order: pick(layout, 'order', []), sections: pick(layout, 'sections', {}),
  email: { subject: pick(em, 'subject', '{title} {period_start} - {period_end}'), body: pick(em, 'body', 'Attached is the {title} for {period_start} to {period_end}.') }, _raw_keys: Object.keys(layout || {}), _raw_email_keys: Object.keys(em || {}), _is_obj: layout !== null && typeof layout === 'object' && !Array.isArray(layout) };
const it = $input.first();
return [{ json: { ...it.json, layout: norm } }];

const C = $('CONFIG').first().json;
const inp = $input.first().json;
const manual = inp.headers !== undefined;
const triggered_by = manual ? 'manual' : 'schedule';
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const reject = (status, error, details) => [{ json: { ok: false, triggered_by, http_status: status, response_body: { error, ...(details ? { details } : {}) }, notifications: manual ? [] : [{ text: `Scheduled run did not start: ${error}${details ? ' (' + details.join('; ') + ')' : ''}` }] } }];

if (manual && C.REPORT_AUTH_TOKEN && (inp.headers || {})['x-report-token'] !== C.REPORT_AUTH_TOKEN) return reject(401, 'unauthorized');

// ---- CONFIG sanity
const bad = [];
const url = (v) => /^https?:\/\//.test(v || '');
for (const k of ['REPORT_STORE_API_URL', 'GOTENBERG_API_URL', 'DISTRIBUTION_API_URL', 'NOTIFY_API_URL']) if (!url(C[k])) bad.push(`CONFIG.${k} must start with http:// or https://`);
if (C.SLACK_WEBHOOK_URL && !url(C.SLACK_WEBHOOK_URL)) bad.push('CONFIG.SLACK_WEBHOOK_URL must be blank or start with http(s)://');
for (const k of ['SERVICE_HEADERS_JSON', 'GOTENBERG_HEADERS_JSON']) { try { if (!isObj(JSON.parse(C[k] || '{}'))) throw 0; } catch (e) { bad.push(`CONFIG.${k} must be a JSON object`); } }
const EMAIL = /^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/;
if (C.FALLBACK_RECIPIENT_EMAIL && !EMAIL.test(C.FALLBACK_RECIPIENT_EMAIL)) bad.push('CONFIG.FALLBACK_RECIPIENT_EMAIL must be blank or a valid email address');
if (!/^[A-Za-z0-9._-]{1,64}$/.test(C.REPORT_NAME || '')) bad.push('CONFIG.REPORT_NAME must be 1-64 characters: letters, digits and . _ -');
if (typeof C.REPORT_TITLE !== 'string' || !C.REPORT_TITLE.trim() || C.REPORT_TITLE.length > 120) bad.push('CONFIG.REPORT_TITLE must be 1-120 characters');
for (const k of ['MAX_RECIPIENTS', 'MAX_PERIOD_DAYS', 'PROCESSING_TTL_SECONDS', 'SOURCE_TIMEOUT_MS', 'PDF_TIMEOUT_MS', 'EMAIL_TIMEOUT_MS', 'REQUEST_TIMEOUT_MS']) if (!(Number(C[k]) > 0)) bad.push(`CONFIG.${k} must be a number > 0`);
