  const raw = JSON.parse(C.DATA_SOURCES_JSON);
  if (!Array.isArray(raw) || !raw.length) throw new Error('DATA_SOURCES_JSON must be a non-empty JSON array');
  const seen = new Set();
  raw.forEach((s, i) => {
    const w = `DATA_SOURCES_JSON[${i}]`;
    if (!isObj(s)) { bad.push(`${w} must be an object`); return; }
    if (typeof s.name !== 'string' || !/^[A-Za-z0-9._-]{1,64}$/.test(s.name)) bad.push(`${w}.name must be 1-64 characters: letters, digits and . _ -`);
    else if (seen.has(s.name)) bad.push(`${w}.name "${s.name}" is used twice`); else seen.add(s.name);
    if (!url(s.url)) bad.push(`${w}.url must start with http(s)://`);
    if (s.label !== undefined && (typeof s.label !== 'string' || !s.label.trim() || s.label.length > 100)) bad.push(`${w}.label must be a 1-100 character string`);
    if (s.headers !== undefined && !isObj(s.headers)) bad.push(`${w}.headers must be an object`);
    if (s.required !== undefined && typeof s.required !== 'boolean') bad.push(`${w}.required must be true or false`);
    const t = s.timeout_ms === undefined ? Number(C.SOURCE_TIMEOUT_MS) : Number(s.timeout_ms);
    if (!(t > 0 && t <= 300000)) bad.push(`${w}.timeout_ms must be between 1 and 300000`);
    sources.push({ name: s.name, label: (s.label || s.name).trim(), url: s.url, headers: isObj(s.headers) ? s.headers : {}, required: s.required === true, timeout_ms: t });
  });
} catch (e) { bad.push('CONFIG.DATA_SOURCES_JSON is not valid: ' + e.message); }
// ---- the Report Layout node
{
  const L = $('Report Layout').first().json.layout;
  const lb = (m) => bad.push('Layout: ' + m);
  const names = sources.map((s) => s.name);
  const str = (v, min, max) => typeof v === 'string' && v.length >= min && v.length <= max;
  const strList = (v, max) => Array.isArray(v) && v.length <= max && v.every((x) => str(x, 1, 64)) && new Set(v).size === v.length;
  const FORMATS = ['number', 'int', 'money', 'percent', 'date', 'text'];
  if (!L._is_obj) lb('layout must be an object');
  else {
    for (const k of L._raw_keys) if (!['css', 'intro', 'footer', 'currency', 'order', 'sections', 'email', 'page', 'theme', 'kpis'].includes(k)) lb(`${k} is not a known setting (css, intro, footer, currency, order, sections, email, page, theme, kpis)`);
    if (L.page !== null) {
      if (!isObj(L.page)) lb('page must be an object (or null)');
      else {
        for (const k of Object.keys(L.page)) if (!['size', 'landscape', 'margin_mm'].includes(k)) lb(`page.${k} is not a known setting (size, landscape, margin_mm)`);
        if (L.page.size !== undefined && !['A4', 'A3', 'Letter', 'Legal'].includes(L.page.size)) lb('page.size must be A4, A3, Letter or Legal');
        if (L.page.landscape !== undefined && typeof L.page.landscape !== 'boolean') lb('page.landscape must be true or false');
        if (L.page.margin_mm !== undefined && !(typeof L.page.margin_mm === 'number' && L.page.margin_mm >= 0 && L.page.margin_mm <= 50)) lb('page.margin_mm must be a number from 0 to 50');
      }
    }
    if (L.theme !== null) {
      if (!isObj(L.theme)) lb('theme must be an object (or null)');
      else {
        for (const k of Object.keys(L.theme)) if (!['accent', 'font', 'font_size'].includes(k)) lb(`theme.${k} is not a known setting (accent, font, font_size)`);
        if (L.theme.accent !== undefined && !/^#[0-9a-fA-F]{6}$/.test(L.theme.accent)) lb('theme.accent must be a colour written like #0b5394');
        if (L.theme.font !== undefined && !['sans', 'serif', 'mono'].includes(L.theme.font)) lb('theme.font must be sans, serif or mono');
        if (L.theme.font_size !== undefined && !(Number.isInteger(L.theme.font_size) && L.theme.font_size >= 8 && L.theme.font_size <= 18)) lb('theme.font_size must be a whole number from 8 to 18');
      }
    }
    if (!Array.isArray(L.kpis) || L.kpis.length > 8) lb('kpis must be a list of at most 8 figures');
    else L.kpis.forEach((k, i) => {
      const w = `kpis[${i}]`;
      if (!isObj(k)) { lb(`${w} must be an object`); return; }
      for (const x of Object.keys(k)) if (!['source', 'key', 'label', 'format', 'agg', 'column'].includes(x)) lb(`${w}.${x} is not a known setting (source, key, label, format, agg, column)`);
      if (!names.includes(k.source)) lb(`${w}.source must be a data source name from DATA_SOURCES_JSON (known names: ${names.join(', ')})`);
      if (k.key !== undefined && !(typeof k.key === 'string' && /^[A-Za-z0-9_.-]{1,100}$/.test(k.key))) lb(`${w}.key must be a key name or dotted path (letters, digits, _ . -)`);
      if (k.label !== undefined && !str(k.label, 1, 60)) lb(`${w}.label must be 1 to 60 characters`);
      if (k.format !== undefined && !FORMATS.includes(k.format)) lb(`${w}.format must be one of ${FORMATS.join(', ')}`);
      if (k.agg !== undefined && !['sum', 'avg', 'min', 'max', 'count'].includes(k.agg)) lb(`${w}.agg must be sum, avg, min, max or count`);
      if (k.agg === undefined && k.key === undefined) lb(`${w} needs a key (or an agg for a source that is a list)`);
      if (k.agg !== undefined && k.agg !== 'count' && !(typeof k.column === 'string' && /^[A-Za-z0-9_.-]{1,64}$/.test(k.column))) lb(`${w}.column is needed for agg "${k.agg}" (the column to ${k.agg})`);
      if (k.column !== undefined && k.agg === undefined) lb(`${w}.column only makes sense together with agg`);
    });
    if (!str(L.css, 0, 5000) || /[<>]/.test(L.css) || /@import|url\s*\(|expression\s*\(/i.test(L.css)) lb('css must be text of at most 5000 characters with no < or >, no @import and no url(...)');
    if (!str(L.intro, 0, 1000)) lb('intro must be text of at most 1000 characters');
    if (!str(L.footer, 0, 1000)) lb('footer must be text of at most 1000 characters');
    if (!str(L.currency, 0, 5)) lb('currency must be text of at most 5 characters');
    if (!strList(L.order, 100) || !L.order.every((n) => names.includes(n))) lb('order must be a list of different data source names from DATA_SOURCES_JSON (known names: ' + names.join(', ') + ')');
    if (!isObj(L.sections)) lb('sections must be an object');
    else for (const [n, sec] of Object.entries(L.sections)) {
      const w = `sections.${n}`;
      if (!names.includes(n)) { lb(`${w}: "${n}" is not a data source name from DATA_SOURCES_JSON (known names: ${names.join(', ')})`); continue; }
      if (!isObj(sec)) { lb(`${w} must be an object`); continue; }
      for (const k of Object.keys(sec)) if (!['title', 'show', 'hide', 'labels', 'formats', 'max_rows', 'empty_text', 'note', 'style', 'sort', 'total', 'highlight'].includes(k)) lb(`${w}.${k} is not a known setting (title, show, hide, labels, formats, max_rows, empty_text, note, style, sort, total, highlight)`);
      if (sec.style !== undefined && !['table', 'cards'].includes(sec.style)) lb(`${w}.style must be table or cards`);
      if (sec.sort !== undefined) {
        if (!isObj(sec.sort) || !str(sec.sort.by, 1, 64) || (sec.sort.order !== undefined && !['asc', 'desc'].includes(sec.sort.order)) || Object.keys(sec.sort).some((k) => !['by', 'order'].includes(k))) lb(`${w}.sort must be { by: 'column', order: 'asc' or 'desc' }`);
      }
      if (sec.total !== undefined && !strList(sec.total, 20)) lb(`${w}.total must be a list of at most 20 different column names`);
      if (sec.highlight !== undefined) {
        if (!Array.isArray(sec.highlight) || sec.highlight.length > 20) lb(`${w}.highlight must be a list of at most 20 rules`);
        else sec.highlight.forEach((h, j) => {
          const hw = `${w}.highlight[${j}]`;
          if (!isObj(h)) { lb(`${hw} must be an object`); return; }
          for (const k of Object.keys(h)) if (!['key', 'op', 'value', 'tone'].includes(k)) lb(`${hw}.${k} is not a known setting (key, op, value, tone)`);
          if (!str(h.key, 1, 64)) lb(`${hw}.key must be a key or column name`);
          if (!['>', '>=', '<', '<=', '==', '!='].includes(h.op)) lb(`${hw}.op must be one of > >= < <= == !=`);
          if (!((typeof h.value === 'number' && isFinite(h.value)) || str(h.value, 0, 100))) lb(`${hw}.value must be a number or text of at most 100 characters`);
          else if (typeof h.value === 'string' && !['==', '!='].includes(h.op)) lb(`${hw}: text values only work with == and !=`);
          if (!['good', 'warn', 'bad'].includes(h.tone)) lb(`${hw}.tone must be good, warn or bad`);
        });
      }
      if (sec.title !== undefined && !str(sec.title, 1, 100)) lb(`${w}.title must be 1 to 100 characters`);
      for (const k of ['show', 'hide']) if (sec[k] !== undefined && !strList(sec[k], 50)) lb(`${w}.${k} must be a list of at most 50 different key names`);
      if (sec.labels !== undefined && !(isObj(sec.labels) && Object.keys(sec.labels).length <= 50 && Object.values(sec.labels).every((x) => str(x, 1, 60)))) lb(`${w}.labels must be an object of key -> heading (1 to 60 characters)`);
      if (sec.formats !== undefined && !(isObj(sec.formats) && Object.keys(sec.formats).length <= 50 && Object.values(sec.formats).every((x) => FORMATS.includes(x)))) lb(`${w}.formats must be an object of key -> one of ${FORMATS.join(', ')}`);
      if (sec.max_rows !== undefined && !(Number.isInteger(sec.max_rows) && sec.max_rows >= 1 && sec.max_rows <= 500)) lb(`${w}.max_rows must be a whole number from 1 to 500`);
      for (const k of ['empty_text', 'note']) if (sec[k] !== undefined && !str(sec[k], 1, 300)) lb(`${w}.${k} must be 1 to 300 characters`);
    }
    if (!isObj(L.email)) lb('email must be an object');
    else {
      for (const k of L._raw_email_keys) if (!['subject', 'body'].includes(k)) lb(`email.${k} is not a known setting (subject, body)`);
      const PH = ['title', 'period_start', 'period_end', 'run_id'];
      const phOk = (t) => [...t.matchAll(/\{([A-Za-z_]+)\}/g)].every((m) => PH.includes(m[1]));
      if (!str(L.email.subject, 1, 200) || /[\r\n]/.test(L.email.subject)) lb('email.subject must be one line of 1 to 200 characters');
      else if (!phOk(L.email.subject)) lb('email.subject uses an unknown {placeholder} (allowed: {title} {period_start} {period_end} {run_id})');
      if (!str(L.email.body, 1, 2000)) lb('email.body must be 1 to 2000 characters');
      else if (!phOk(L.email.body)) lb('email.body uses an unknown {placeholder} (allowed: {title} {period_start} {period_end} {run_id})');
