if (bad.length) return reject(500, 'report_misconfigured', bad);

// ---- the period
const DAY = 86400000;
const parseDate = (s) => { if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null; const d = new Date(s + 'T00:00:00Z'); return !isNaN(d) && d.toISOString().slice(0, 10) === s ? d : null; };
let period_start, period_end, force = false;
if (manual) {
  const b = inp.body;
  if (!isObj(b)) return reject(400, 'validation_failed', ['body must be a JSON object']);
  const errors = [];
  const ds = parseDate(b.period_start), de = parseDate(b.period_end);
  if (!ds) errors.push('period_start must be a real ISO date (YYYY-MM-DD)');
  if (!de) errors.push('period_end must be a real ISO date (YYYY-MM-DD)');
  if (ds && de) {
