  period_end = new Date(thisMonday - 1 * DAY).toISOString().slice(0, 10);
}
const run_id = `${C.REPORT_NAME}-${period_start}_${period_end}`;
return [{ json: { ok: true, triggered_by, force, period_start, period_end, run_id, sources, tail: null } }];

const Pl = $('Plan Run').first().json;
const r = $input.first().json;
const b = r.statusCode === 200 && r.body && typeof r.body === 'object' ? r.body : null;
const manual = Pl.triggered_by === 'manual';
const end = (status, body, notes = []) => [{ json: { ok: false, claimed: false, triggered_by: Pl.triggered_by, http_status: status, response_body: body, notifications: notes } }];
if (!b || typeof b.claimed !== 'boolean') {
  return end(503, { error: 'report_store_unavailable', run_id: Pl.run_id, retry: true }, [{ text: `Run ${Pl.run_id} not started: the report store could not be reached, so exactly-once delivery cannot be guaranteed.` }]);
}
const rec = b.record && typeof b.record === 'object' ? b.record : {};
