  if (rec.status === 'sent') return end(200, { status: 'skipped_already_sent', run_id: Pl.run_id });
  return end(409, { error: 'run_in_progress', run_id: Pl.run_id, status: rec.status || 'processing' });
}
const delivered_before = Array.isArray(rec.delivered) ? rec.delivered.filter((x) => typeof x === 'string') : [];
return [{ json: { ok: true, claimed: true, delivered_before } }];

const Pl = $('Plan Run').first().json;
return Pl.sources.map((s, i) => {
  const base = s.url.split('#')[0];
  const url = base + (base.includes('?') ? '&' : '?') + 'start=' + encodeURIComponent(Pl.period_start) + '&end=' + encodeURIComponent(Pl.period_end);
  return { json: { i, name: s.name, url, headers: s.headers, timeout_ms: s.timeout_ms } };
});

const classify = (r, s) => {
  const base = { name: s.name, label: s.label, required: s.required };
  if (r.error !== undefined || typeof r.statusCode !== 'number') return { ...base, available: false, retriable: true, detail: 'request failed: ' + String((r.error && (r.error.message || r.error)) || 'no response').slice(0, 160) };
  if (r.statusCode >= 400) return { ...base, available: false, retriable: r.statusCode >= 500 || r.statusCode === 408 || r.statusCode === 429, detail: 'HTTP ' + r.statusCode };
  const d = r.body;
  if (d === null || typeof d !== 'object') return { ...base, available: false, retriable: false, detail: 'response was not JSON data' };   // e.g. an HTML maintenance page
