};
const summarize = (out) => {
  const missing = out.filter((s) => !s.available);
  const required_missing = missing.filter((s) => s.required).map((s) => s.name);
  let fail = null;
  if (!out.some((s) => s.available)) fail = { status: 'failed_no_data', http_status: 502, detail: 'every data source was unavailable', key: 'no_data' };
  else if (required_missing.length) fail = { status: 'failed_required_source_unavailable', http_status: 502, detail: 'required source unavailable: ' + required_missing.join(', '), key: 'required_source' };
