const classify = (r, s) => {
  const base = { name: s.name, label: s.label, required: s.required };
  if (r.error !== undefined || typeof r.statusCode !== 'number') return { ...base, available: false, retriable: true, detail: 'request failed: ' + String((r.error && (r.error.message || r.error)) || 'no response').slice(0, 160) };
  if (r.statusCode >= 400) return { ...base, available: false, retriable: r.statusCode >= 500 || r.statusCode === 408 || r.statusCode === 429, detail: 'HTTP ' + r.statusCode };
  const d = r.body;
