  const required_missing = missing.filter((s) => s.required).map((s) => s.name);
  let fail = null;
  if (!out.some((s) => s.available)) fail = { status: 'failed_no_data', http_status: 502, detail: 'every data source was unavailable', key: 'no_data' };
